/*
 * FIDO2 credential store — TROPIC01-backed.
 *
 * Each FIDO2 credential maps 1:1 to:
 *   - TROPIC01 ECC slot N (0..28)         — Ed25519 private key, on chip
 *   - TROPIC01 R-mem slot N+1             — metadata (rp_id_hash, nonce, ...)
 *
 * Slots 29-31 are reserved for OpenPGP card sig/dec/aut (see
 * firmware/src/openpgp/pgp_keys.h).
 *
 * Private keys are generated by lt_ecc_key_generate inside the
 * TROPIC01 chip — they NEVER exist in STM32 RAM or flash.  Signatures
 * come from lt_ecc_eddsa_sign which performs the EdDSA computation
 * (RFC 8032) on-chip.  This is the core security property of the
 * device: a firmware compromise cannot exfiltrate FIDO credentials.
 *
 * Signature counter: a single SHARED monotonic counter (TROPIC01 hw
 * counter 0).  Per WebAuthn Level 2 §6.1.1 a shared counter is
 * compliant.  Initialized to TR01_MCOUNTER_VALUE_MAX (0xFFFFFFFE) on a
 * genuine first boot or by authenticatorReset, then decremented per
 * assertion; observed signCount =
 * MAX − chip_value, so it increases over time.  At 1 signature/sec
 * continuous the counter exhausts after ~136 years.
 *
 * Phase 9 M3: an assertion reserves its value first (Update, then Get)
 * and signs that value; a failure afterwards leaves a gap, which RPs
 * accept, instead of a repeated value, which they treat as a clone.
 * Counter errors fail the operation; there is no fallback value.
 *
 * Future work — per-credential counters
 * (if RP compatibility testing shows a benefit). Phase 5 keeps it shared.
 */

#ifndef NIXTROPIC_FIDO_HID_CREDSTORE_H
#define NIXTROPIC_FIDO_HID_CREDSTORE_H

#include <stdint.h>
#include <stddef.h>

#include "slots.h"  /* SLOTS_CRED_ID_LEN, SLOTS_RP_ID_HASH_LEN */

/* Largest public key (P-256 x || y) and signature (ES256 DER), Phase 9 M3b. */
#define CREDSTORE_PUBKEY_MAX    64u
#define CREDSTORE_SIG_MAX       72u
#define CREDSTORE_CRED_ID_LEN   SLOTS_CRED_ID_LEN   /* 18 B */

/* Opaque handle returned by credstore_make / credstore_lookup. Internally
 * just the slot index (0..31), but callers should treat it as opaque so
 * we can change the representation later. */
typedef int credstore_handle_t;

#define CREDSTORE_INVALID_HANDLE (-1)

/**
 * @brief Initialize the credential store.
 *        fido_state_boot(): O1 + PIN binding + signature counter (design
 *        §4; an absent O1 = checked wipe, anything unusable = only
 *        authenticatorReset works).  Idempotent once it succeeded.
 *
 * @return 0 on success; negative on TROPIC01 error.
 */
int credstore_init(void);

/**
 * @brief Create a new credential — generate fresh Ed25519 keypair on
 *        TROPIC01, allocate a slot, persist metadata, return the bits
 *        the host's MakeCredential response needs.
 *
 * Phase 9 M3: the key is generated and read back in a FREE slot first;
 * only then does slots_alloc publish it (metadata, then one bitmap write
 * that also drops `replace_mask`).  A failure before publication erases
 * the new key again.
 *
 * @param  rp_id_hash    SHA-256(rpId) — 32 bytes
 * @param  alg           SLOTS_ALG_ED25519 (Ed25519 key) or SLOTS_ALG_ES256
 *                       (P-256 key); anything else is an error (-2)
 * @param  flags         SLOTS_FLAG_RESIDENT for a discoverable credential
 * @param  created       creation sequence (see slot_meta_t)
 * @param  replace_mask  slots this credential replaces (same RP + user)
 * @param  out_pubkey    public key: 32 B Ed25519, or 64 B P-256 x || y
 * @param  out_cred_id   18-byte credentialId for the relying party
 * @param  out_handle    Handle for the immediate MakeCred self-attestation
 *                       sign — pass to credstore_sign.
 * @return 0 on success; -1 if out of slots; -2 on chip error
 */
int credstore_make(const uint8_t rp_id_hash[SLOTS_RP_ID_HASH_LEN],
                   uint8_t alg, uint8_t flags,
                   const uint8_t *user_handle, size_t user_handle_len,
                   uint32_t created, uint32_t replace_mask,
                   uint8_t out_pubkey[CREDSTORE_PUBKEY_MAX],
                   uint8_t out_cred_id[CREDSTORE_CRED_ID_LEN],
                   credstore_handle_t *out_handle);

/**
 * @brief Resolve a credential ID from a relying party to an internal
 *        handle for signing.
 *
 *   1. slots_lookup_by_credid — validates version/slot_idx/nonce CT-cmp
 *   2. Returns the slot index as a handle
 *
 * @return 0 on success (out_handle populated); -1 if not found
 */
int credstore_lookup(const uint8_t *cred_id, size_t cred_id_len,
                     credstore_handle_t *out_handle);

/**
 * @brief Sign a message with the key in the slot identified by the
 *        handle. The chip performs the EdDSA / ECDSA computation — the
 *        private key never leaves TROPIC01.
 *
 * @param  h           Handle from credstore_make / credstore_lookup
 * @param  alg         The credential's stored SLOTS_ALG_*
 * @param  msg         Bytes to sign (typically authData || clientDataHash)
 * @param  msg_len     Length of msg (EdDSA: max 4096 per TROPIC01 spec)
 * @param  out_sig     EdDSA: 64 raw bytes; ES256: DER, up to 72 bytes
 * @return signature length; -1 on parameter error; -2 on chip error
 */
int credstore_sign(credstore_handle_t h, uint8_t alg,
                   const uint8_t *msg, size_t msg_len,
                   uint8_t out_sig[CREDSTORE_SIG_MAX]);

/**
 * @brief Find a credential by ID, bound to the given RP (Phase 9 M3):
 *        succeeds only if the ID resolves AND its stored rpIdHash equals
 *        rp_id_hash.  out_meta (optional) receives the slot metadata.
 * @return 0 on success; -1 if not found or bound to another RP.
 */
int credstore_find(const uint8_t *cred_id, size_t cred_id_len,
                   const uint8_t rp_id_hash[SLOTS_RP_ID_HASH_LEN],
                   credstore_handle_t *out_handle, slot_meta_t *out_meta);

/**
 * @brief Current signCount without advancing it (MakeCredential).
 * @return 0 on success; negative on a counter error (never a fake 0).
 */
int credstore_signcount_peek(uint32_t *out);

/**
 * @brief Reserve the next signCount for an assertion: Update the chip
 *        counter, then read it.  A later failure leaves a gap, never a
 *        repeat.  No retry (an ambiguous Update may have run).
 * @return 0 on success; negative on a counter error.
 */
int credstore_signcount_next(uint32_t *out);

/* ===== Phase 6 M3: read + delete helpers for credentialManagement ===== */

/**
 * @brief Read public key for the credential in the given slot; its
 *        length must match the stored `alg` (SLOTS_ALG_*).
 * @return the key length (32 or 64); -1 on chip error or a mismatch.
 */
int credstore_get_pubkey(int slot_idx, uint8_t alg,
                         uint8_t out_pubkey[CREDSTORE_PUBKEY_MAX]);

/**
 * @brief Erase a single credential — ECC slot + R-mem slot, clear bitmap.
 *        Uses the mutation-busy lock (see credstore_is_mutating).
 * @return 0 on success; -1 on out-of-range; -2 on chip error.
 */
int credstore_erase_slot(int slot_idx);

/**
 * @brief True while a credstore-mutating operation is in flight (currently
 *        only credstore_make and credstore_erase_slot raise it).  Used by
 *        MakeCred/GetAssertion to refuse concurrent activity per H2.
 */
int credstore_is_mutating(void);

/**
 * @brief Factory reset: wipe ALL FIDO credentials.
 *
 *   fido_state_wipe() (Phase 9 M4): FIDO keys → metadata → PIN binding
 *   → fresh O1 → signature counter, each step checked; a failure stops
 *   it before the PIN is cleared or defaults are written.
 *
 * After this, the authenticator looks like a fresh device. Used by
 * authenticatorReset (CTAP2 cmd 0x07) and by the lt-rpc debug
 * SLOTS_RESET command.
 *
 * @return 0 on success; negative on chip error.
 */
int credstore_factory_reset(void);

/**
 * @brief 1 if FIDO state was validated at boot (or freshly wiped by a
 *        completed reset) and no write to O1 or the PIN binding O2 has
 *        failed since.  The CTAP
 *        dispatcher serves only GetInfo and authenticatorReset otherwise
 *        (design §4/§6; no re-initialisation at runtime).
 */
int credstore_ready(void);

#endif /* NIXTROPIC_FIDO_HID_CREDSTORE_H */
